  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Siklus Rankine adalah siklus daya ideal yang paling umum digunakan pada...','[{"key": "A", "text": "Mesin jet"}, {"key": "B", "text": "Pembangkit Listrik Tenaga Uap (PLTU)"}, {"key": "C", "text": "Mesin diesel"}, {"key": "D", "text": "Kulkas"}]'::jsonb,'A','Siklus Rankine adalah model siklus daya uap ideal yang menjadi dasar operasional dari sebagian besar pembangkit listrik tenaga uap (PLTU) di seluruh dunia. Siklus ini menggunakan fluida kerja, biasanya air, yang mengalami perubahan fasa dari cair menjadi uap superpanas di dalam boiler, kemudian berekspansi di turbin untuk menghasilkan kerja (memutar generator), didinginkan kembali menjadi cair di kondensor, dan terakhir dipompa kembali ke boiler. Siklus ini berbeda dari siklus mesin jet (Brayton) atau mesin diesel.','AKDING',3);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pada siklus Brayton ideal, proses kompresi dan ekspansi berlangsung secara...','[{"key": "A", "text": "Isobarik"}, {"key": "B", "text": "Isokhorik"}, {"key": "C", "text": "Isotermal"}, {"key": "D", "text": "Isentropik (adiabatik reversibel)"}]'::jsonb,'A','Dalam analisis ideal dari Siklus Brayton, yang menjadi dasar mesin turbin gas dan mesin jet, proses kompresi udara dan proses ekspansi gas panas di turbin diasumsikan berlangsung secara isentropik. Proses isentropik adalah proses yang bersifat adiabatik (tidak ada perpindahan panas dengan lingkungan) dan reversibel (tidak ada kerugian akibat gesekan atau inefisiensi lainnya). Asumsi ini menyederhanakan analisis dan memberikan batas atas kinerja teoretis dari siklus tersebut.','AKDING',4);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Perbedaan utama antara siklus Rankine dan siklus Carnot untuk aplikasi uap adalah bahwa pada siklus Rankine, proses pemompaan terjadi pada fasa...','[{"key": "A", "text": "Cair jenuh"}, {"key": "B", "text": "Uap superpanas"}, {"key": "C", "text": "Campuran cair-uap"}, {"key": "D", "text": "Gas"}]'::jsonb,'A','Perbedaan praktis yang signifikan antara Siklus Rankine dan Siklus Carnot saat diaplikasikan pada uap adalah pada tahap penambahan tekanan. Pada Siklus Rankine, fluida kerja (air) didinginkan di kondensor hingga menjadi fasa cair jenuh sepenuhnya sebelum dipompa ke tekanan boiler yang tinggi. Memompa cairan membutuhkan kerja yang jauh lebih kecil dibandingkan dengan mengkompresi campuran uap-cair seperti yang disyaratkan oleh Siklus Carnot, sehingga membuat Siklus Rankine lebih mudah diimplementasikan secara praktis.','AKDING',5);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Komponen utama dalam siklus Brayton yang berfungsi untuk menaikkan tekanan udara adalah...','[{"key": "A", "text": "Turbin"}, {"key": "B", "text": "Kondensor"}, {"key": "C", "text": "Kompresor"}, {"key": "D", "text": "Boiler"}]'::jsonb,'A','Siklus Brayton terdiri dari empat komponen utama: kompresor, ruang bakar, turbin, dan saluran keluar. Kompresor memiliki fungsi vital untuk menarik udara dari lingkungan sekitar dan menaikkan tekanannya secara signifikan. Udara bertekanan tinggi ini kemudian dialirkan ke ruang bakar untuk dicampur dengan bahan bakar dan dibakar, menghasilkan gas panas berenergi tinggi yang akan berekspansi di turbin.','AKDING',6);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Persamaan kontinuitas untuk aliran fluida tak termampatkan (incompressible) menyatakan bahwa jika luas penampang pipa mengecil, maka kecepatan aliran fluida akan...','[{"key": "A", "text": "Menurun"}, {"key": "B", "text": "Tetap"}, {"key": "C", "text": "Meningkat"}, {"key": "D", "text": "Menjadi nol"}]'::jsonb,'A','Persamaan kontinuitas adalah prinsip dasar dalam mekanika fluida yang menyatakan konservasi massa. Untuk aliran fluida yang tidak dapat dimampatkan (incompressible), seperti air pada kecepatan rendah, persamaan ini dapat disederhanakan menjadi $A1V1 = A2V2. Di sini, A adalah luas penampang aliran dan V adalah kecepatan aliran. Persamaan ini menunjukkan bahwa hasil kali antara luas penampang dan kecepatan (yang merupakan debit volume) harus konstan. Akibatnya, jika pipa menyempit (luas penampang A mengecil), kecepatan aliran V harus meningkat untuk menjaga debit tetap sama.','AKDING',7);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Prinsip Bernoulli menyatakan hubungan antara...','[{"key": "A", "text": "Tekanan, massa jenis, dan temperatur"}, {"key": "B", "text": "Kecepatan, viskositas, dan tekanan"}, {"key": "C", "text": "Tekanan, kecepatan, dan ketinggian (elevasi)"}, {"key": "D", "text": "Gaya, massa, dan percepatan"}]'::jsonb,'A','Prinsip Bernoulli adalah bentuk dari hukum kekekalan energi yang diterapkan pada fluida yang bergerak. Prinsip ini menyatakan bahwa untuk aliran fluida yang ideal (tanpa viskositas dan inkompresibel), jumlah dari energi tekanan, energi kinetik per satuan volume (yang bergantung pada kecepatan), dan energi potensial per satuan volume (yang bergantung pada ketinggian) adalah konstan di sepanjang garis aliran. Prinsip ini menjelaskan fenomena seperti mengapa sayap pesawat dapat menghasilkan gaya angkat.','AKDING',8);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Aliran fluida dalam pipa pendingin dikatakan turbulen jika bilangan Reynolds-nya...','[{"key": "A", "text": "Kurang dari 2000"}, {"key": "B", "text": "Tepat 2300"}, {"key": "C", "text": "Antara 2000 dan 4000"}, {"key": "D", "text": "Lebih dari 4000"}]'::jsonb,'A','Karakteristik aliran fluida dalam pipa, apakah laminar atau turbulen, ditentukan oleh sebuah parameter tak berdimensi yang disebut Bilangan Reynolds (Re). Bilangan ini merepresentasikan rasio antara gaya inersia terhadap gaya viskos. Berdasarkan pengamatan eksperimental, secara umum disepakati bahwa aliran dalam pipa dianggap laminar jika Re < 2000, turbulen jika Re > 4000, dan berada dalam daerah transisi di antara kedua nilai tersebut. Aliran turbulen ditandai oleh adanya pusaran dan pergerakan acak partikel fluida.','AKDING',9);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah pipa mengalirkan air dengan debit 0.5 m³/s. Jika luas penampang pipa adalah 0.1 m², berapakah kecepatan rata-rata aliran air di dalam pipa?','[{"key": "A", "text": "0.5 m/s"}, {"key": "B", "text": "2 m/s"}, {"key": "C", "text": "5 m/s"}, {"key": "D", "text": "10 m/s"}]'::jsonb,'A','Kecepatan rata-rata aliran fluida di dalam sebuah pipa dapat dihitung menggunakan hubungan dasar antara debit volume (Q), luas penampang (A), dan kecepatan (v), yaitu Q = A x v. Untuk menemukan kecepatan, kita dapat mengatur ulang rumus tersebut menjadi v = Q  / A. Dengan data yang diberikan, debit Q adalah 0.5 m³/s dan luas penampang A adalah 0.1 m². Maka, perhitungannya adalah v = 0.5 m³/s  :  0.1 m² = 5 m/s.','AKDING',10);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Aliran yang ditandai dengan pergerakan partikel fluida yang teratur dan berlapis-lapis disebut aliran...','[{"key": "A", "text": "Transisi"}, {"key": "B", "text": "Turbulen"}, {"key": "C", "text": "Kompresibel"}, {"key": "D", "text": "Laminar"}]'::jsonb,'A','Aliran laminar adalah jenis aliran fluida di mana partikel-partikel fluida bergerak dalam lintasan yang mulus, teratur, dan sejajar, seolah-olah membentuk lapisan-lapisan (lamina) yang meluncur satu sama lain tanpa percampuran yang signifikan. Aliran ini biasanya terjadi pada kecepatan yang relatif rendah dan pada fluida dengan viskositas tinggi. Contohnya adalah aliran madu yang dituang atau aliran darah di pembuluh kapiler.','AKDING',11);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam aplikasi pipa pendingin, aliran yang lebih disukai untuk meningkatkan perpindahan panas adalah aliran...','[{"key": "A", "text": "Laminar"}, {"key": "B", "text": "Turbulen"}, {"key": "C", "text": "Stasioner"}, {"key": "D", "text": "Seragam"}]'::jsonb,'A','Dalam aplikasi rekayasa seperti pipa pendingin atau penukar panas (heat exchanger), tujuan utamanya adalah memaksimalkan laju perpindahan panas. Aliran turbulen, dengan gerakannya yang acak dan bergejolak, menyebabkan percampuran fluida yang jauh lebih baik dibandingkan aliran laminar. Percampuran ini secara efektif membawa fluida yang lebih panas (atau lebih dingin) untuk bersentuhan dengan dinding pipa, sehingga secara drastis meningkatkan koefisien perpindahan panas konveksi dan membuat proses pendinginan menjadi lebih efisien.','AKDING',12);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Perpindahan panas yang terjadi melalui getaran molekul dalam medium padat tanpa adanya perpindahan massa disebut...','[{"key": "A", "text": "Konduksi"}, {"key": "B", "text": "Konveksi"}, {"key": "C", "text": "Radiasi"}, {"key": "D", "text": "Adveksi"}]'::jsonb,'A','Konduksi adalah salah satu dari tiga mekanisme dasar perpindahan panas. Proses ini terjadi ketika energi panas berpindah dari satu molekul ke molekul tetangganya melalui getaran dan tumbukan langsung. Konduksi tidak melibatkan perpindahan massa secara makroskopis. Mekanisme ini merupakan cara utama perpindahan panas dalam benda padat, seperti panas yang merambat dari ujung sendok logam yang panas ke ujung yang dingin.','AKDING',13);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Di dalam boiler sebuah PLTU, mode perpindahan panas yang paling dominan dari api pembakaran ke dinding pipa-pipa air adalah...','[{"key": "A", "text": "Konduksi"}, {"key": "B", "text": "Konveksi paksa"}, {"key": "C", "text": "Radiasi"}, {"key": "D", "text": "Konveksi alami"}]'::jsonb,'A','Di dalam lingkungan bersuhu sangat tinggi seperti ruang bakar (furnace) pada boiler, perpindahan panas melalui radiasi termal menjadi sangat dominan. Api dan gas pembakaran yang panas memancarkan energi dalam bentuk gelombang elektromagnetik (inframerah) yang diserap oleh dinding pipa-pipa air. Meskipun konveksi juga terjadi, kontribusi dari radiasi seringkali menjadi yang terbesar dalam aplikasi semacam ini.','AKDING',14);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Perpindahan panas yang terjadi karena pergerakan massa fluida (cair atau gas) disebut...','[{"key": "A", "text": "Konduksi"}, {"key": "B", "text": "Konveksi"}, {"key": "C", "text": "Radiasi"}, {"key": "D", "text": "Difusi"}]'::jsonb,'A','Konveksi adalah mekanisme perpindahan panas yang terjadi melalui pergerakan massa fluida (cairan atau gas). Ketika sebagian fluida dipanaskan, densitasnya biasanya menurun dan ia bergerak ke atas (konveksi alami), atau fluida tersebut dipaksa bergerak oleh pompa atau kipas (konveksi paksa). Pergerakan massa fluida ini membawa energi panas bersamanya, sehingga menyebabkan transfer panas dari satu lokasi ke lokasi lain. Contohnya adalah proses merebus air atau udara panas yang keluar dari pengering rambut.','AKDING',15);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah plat baja panas dibiarkan mendingin di udara ruangan. Proses pendinginan ini terutama terjadi melalui mekanisme...','[{"key": "A", "text": "Konduksi dan radiasi"}, {"key": "B", "text": "Konveksi dan radiasi"}, {"key": "C", "text": "Hanya konveksi"}, {"key": "D", "text": "Hanya konduksi"}]'::jsonb,'A','Sebuah benda panas yang ditempatkan di udara akan mengalami pendinginan melalui dua mekanisme utama secara bersamaan. Pertama, panas akan berpindah ke molekul-molekul udara yang bersentuhan langsung dengan permukaan plat melalui konveksi. Udara yang lebih hangat ini akan naik dan digantikan oleh udara yang lebih dingin. Kedua, permukaan plat yang panas juga akan memancarkan energi panas dalam bentuk radiasi inframerah ke semua benda di sekitarnya yang lebih dingin.','AKDING',16);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Fungsi utama kondensor dalam siklus PLTU adalah untuk memindahkan panas dari uap ke medium pendingin, mengubah fasa uap menjadi...','[{"key": "A", "text": "Gas"}, {"key": "B", "text": "Cair"}, {"key": "C", "text": "Uap jenuh"}, {"key": "D", "text": "Campuran"}]'::jsonb,'A','Kondensor merupakan komponen krusial dalam siklus daya uap. Fungsinya adalah menerima uap bertekanan rendah yang telah melakukan kerja di turbin dan mendinginkannya. Proses pendinginan ini, yang biasanya menggunakan air atau udara sebagai medium pendingin, menyebabkan uap tersebut mengembun dan berubah fasa kembali menjadi cair (disebut air kondensat). Air ini kemudian dapat dipompa kembali ke boiler untuk memulai siklus lagi.','AKDING',17);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kemampuan suatu benda untuk memancarkan energi dalam bentuk gelombang elektromagnetik disebut...','[{"key": "A", "text": "Konduktivitas"}, {"key": "B", "text": "emisivitas"}, {"key": "C", "text": "Absorptivitas"}, {"key": "D", "text": "Reflektivitas"}]'::jsonb,'A','Emisivitas adalah sebuah sifat permukaan material yang mengukur seberapa efektif permukaan tersebut memancarkan energi sebagai radiasi termal. Nilainya berkisar dari 0 hingga 1. Benda hitam sempurna (perfect blackbody), yang merupakan pemancar radiasi ideal, memiliki emisivitas 1, sedangkan permukaan yang sangat reflektif seperti cermin poles memiliki emisivitas mendekati 0.','AKDING',18);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Rasio antara tegangan (stress) dan regangan (strain) pada daerah elastis suatu material dikenal sebagai...','[{"key": "A", "text": "Modulus geser"}, {"key": "B", "text": "Modulus Young (modulus elastisitas)"}, {"key": "C", "text": "Rasio Poisson"}, {"key": "D", "text": "Batas luluh"}]'::jsonb,'A','Modulus Young, sering juga disebut modulus elastisitas, adalah sifat mekanik intrinsik suatu material yang menggambarkan kekakuannya. Sifat ini didefinisikan sebagai rasio antara tegangan (gaya per satuan luas) dan regangan (perubahan panjang per satuan panjang) dalam rentang deformasi elastisnya. Material dengan Modulus Young yang tinggi, seperti baja, akan mengalami deformasi yang kecil ketika diberi beban, yang berarti material tersebut sangat kaku.','AKDING',19);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kegagalan suatu komponen mesin akibat pembebanan yang berulang-ulang (siklik) meskipun tegangan yang terjadi di bawah batas luluh material disebut...','[{"key": "A", "text": "Creep (rayapan)"}, {"key": "B", "text": "Buckling (tekuk)"}, {"key": "C", "text": "Fatigue (kelelahan)"}, {"key": "D", "text": "Fracture (patahan)"}]'::jsonb,'A','Fatigue atau kelelahan material adalah fenomena kegagalan yang terjadi pada komponen yang mengalami pembebanan siklik atau berulang-ulang (misalnya, bergetar atau berputar). Kegagalan ini dapat terjadi meskipun level tegangan maksimum dalam setiap siklusnya berada jauh di bawah kekuatan luluh atau kekuatan tarik material. Seiring waktu, beban yang berulang menyebabkan inisiasi retak mikroskopis yang kemudian merambat hingga komponen tersebut patah secara tiba-tiba.','AKDING',20);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tegangan didefinisikan sebagai...','[{"key": "A", "text": "Perubahan panjang per satuan panjang awal"}, {"key": "B", "text": "Gaya per satuan luas penampang"}, {"key": "C", "text": "Perubahan bentuk akibat gaya"}, {"key": "D", "text": "Energi yang diserap material sebelum patah"}]'::jsonb,'A','Dalam ilmu material dan mekanika, tegangan (stress) adalah ukuran kuantitatif dari gaya-gaya internal yang bekerja di dalam suatu benda sebagai reaksi terhadap gaya eksternal yang diterapkan. Secara matematis, tegangan didefinisikan sebagai gaya yang bekerja pada suatu permukaan dibagi dengan luas permukaan tersebut. Satuan standar untuk tegangan adalah Pascal (N/m²).','AKDING',21);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Material komposit dibuat dengan tujuan untuk...','[{"key": "A", "text": "Mengurangi biaya produksi"}, {"key": "B", "text": "Mendapatkan sifat yang lebih baik dari kombinasi material penyusunnya"}, {"key": "C", "text": "Mempermudah proses daur ulang"}, {"key": "D", "text": "Meningkatkan konduktivitas listrik"}]'::jsonb,'A','Material komposit adalah material rekayasa yang dibuat dengan menggabungkan dua atau lebih material berbeda dengan sifat fisik atau kimia yang berbeda pula. Tujuan utamanya adalah untuk menciptakan sebuah material baru yang memiliki karakteristik gabungan yang lebih unggul daripada masing-masing komponennya secara individual. Contoh klasik adalah beton bertulang (kombinasi beton yang kuat tekan dan baja yang kuat tarik) atau fiber-reinforced polymer (serat kuat dalam matriks polimer ringan).','AKDING',22);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Batas di mana material mulai mengalami deformasi plastis (perubahan bentuk permanen) disebut...','[{"key": "A", "text": "Tegangan ultimate"}, {"key": "B", "text": "Tegangan putus"}, {"key": "C", "text": "Tegangan luluh (yield stress)"}, {"key": "D", "text": "Tegangan izin"}]'::jsonb,'A','Tegangan luluh, atau batas luluh, adalah titik kritis pada kurva tegangan-regangan suatu material. Ini adalah level tegangan di mana material berhenti berperilaku elastis (kembali ke bentuk semula jika beban dihilangkan) dan mulai mengalami deformasi plastis (perubahan bentuk yang permanen). Melampaui titik ini akan menyebabkan perubahan dimensi yang tidak dapat kembali pada komponen.','AKDING',23);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Untuk komponen mesin yang menerima beban impak (tumbukan), sifat material yang paling penting adalah...','[{"key": "A", "text": "Kekerasan (hardness)"}, {"key": "B", "text": "Ketangguhan (toughness)"}, {"key": "C", "text": "Kekakuan (stiffness)"}, {"key": "D", "text": "Keuletan (ductility)"}]'::jsonb,'A','Ketangguhan adalah kemampuan suatu material untuk menyerap energi dan mengalami deformasi plastis yang signifikan sebelum patah. Sifat ini sangat krusial untuk komponen yang dirancang untuk menahan beban kejut atau tumbukan (beban impak). Material yang tangguh (seperti baja tertentu) dapat menyerap banyak energi benturan, sedangkan material yang getas (seperti keramik) akan patah dengan sedikit penyerapan energi.','AKDING',24);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses pemesinan yang bertujuan untuk menghasilkan permukaan yang sangat halus dan akurasi dimensi yang tinggi disebut...','[{"key": "A", "text": "Roughing (pemesinan kasar)"}, {"key": "B", "text": "Turning (bubut)"}, {"key": "C", "text": "Finishing (pemesinan halus)"}, {"key": "D", "text": "Drilling (bor)"}]'::jsonb,'A','Dalam proses manufaktur, pemesinan sering dibagi menjadi beberapa tahap. Tahap finishing adalah tahap akhir yang dilakukan setelah pemesinan kasar (roughing). Tujuannya adalah untuk menghilangkan sejumlah kecil material untuk mencapai dimensi akhir yang sangat presisi, toleransi yang ketat, dan kualitas permukaan (kekasaran) yang sangat halus sesuai dengan spesifikasi desain.','AKDING',25);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Batas penyimpangan ukuran yang diizinkan untuk suatu komponen agar tetap dapat berfungsi dengan baik disebut...','[{"key": "A", "text": "Suaian (fit)"}, {"key": "B", "text": "Toleransi"}, {"key": "C", "text": "Kekasaran permukaan"}, {"key": "D", "text": "Geometri"}]'::jsonb,'A','Dalam gambar teknik dan manufaktur, toleransi adalah total variasi yang diizinkan dalam suatu dimensi. Karena tidak mungkin untuk memproduksi komponen dengan ukuran yang persis sempurna, toleransi menentukan batas atas dan batas bawah dari ukuran yang dapat diterima agar komponen tersebut masih dapat dirakit dengan benar dan berfungsi sesuai tujuannya dalam sebuah rakitan.','AKDING',26);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses perlakuan panas (heat treatment) pada baja yang bertujuan untuk meningkatkan kekerasannya adalah...','[{"key": "A", "text": "Annealing"}, {"key": "B", "text": "Normalizing"}, {"key": "C", "text": "Hardening (pengerasan)"}, {"key": "D", "text": "Tempering"}]'::jsonb,'A','Hardening adalah salah satu jenis perlakuan panas yang bertujuan untuk meningkatkan kekerasan dan kekuatan baja secara signifikan. Proses ini melibatkan pemanasan baja hingga suhu di atas temperatur kritisnya untuk membentuk fasa austenit, kemudian mendinginkannya dengan sangat cepat (proses yang disebut quenching) dalam media seperti air atau oli. Pendinginan cepat ini "mengunci" atom karbon dalam struktur kristal yang sangat tegang dan keras yang disebut martensit.','AKDING',27);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Salah satu tujuan utama dari optimasi proses produksi adalah...','[{"key": "A", "text": "Meningkatkan jumlah tenaga kerja"}, {"key": "B", "text": "Mengurangi biaya dan waktu produksi sambil menjaga kualitas"}, {"key": "C", "text": "Menambah jumlah limbah produksi"}, {"key": "D", "text": "Menggunakan mesin yang paling mahal"}]'::jsonb,'A','Optimasi proses produksi adalah upaya sistematis untuk membuat proses manufaktur seefisien mungkin. Tujuan utamanya adalah untuk memaksimalkan output (jumlah produk) dan kualitas, sambil meminimalkan input (biaya, waktu, tenaga kerja, energi, dan material). Ini melibatkan analisis dan perbaikan berkelanjutan pada setiap langkah dalam lini produksi.','AKDING',28);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses manufaktur yang membentuk logam dengan cara menekannya di antara dua cetakan (dies) disebut...','[{"key": "A", "text": "Pengecoran (casting)"}, {"key": "B", "text": "Pengelasan (welding)"}, {"key": "C", "text": "Penempaan (forging)"}, {"key": "D", "text": "Ekstrusi"}]'::jsonb,'A','Penempaan adalah proses manufaktur di mana logam dibentuk dengan memberikan gaya tekan lokal menggunakan palu atau cetakan (dies). Gaya ini memaksa material untuk mengisi bentuk cetakan. Proses ini biasanya dilakukan pada suhu tinggi (hot forging) dan menghasilkan produk dengan struktur butir yang lebih baik dan sifat mekanik yang unggul, seperti kekuatan dan ketangguhan yang tinggi.','AKDING',29);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'MTBF adalah singkatan dari...','[{"key": "A", "text": "Mean Time Between Failures"}, {"key": "B", "text": "Maximum Time Before Failure"}, {"key": "C", "text": "Mean Time Before Failure"}, {"key": "D", "text": "Minimum Time Between Failures"}]'::jsonb,'A','MTBF, atau Mean Time Between Failures (Waktu Rata-rata Antar Kegagalan), adalah metrik keandalan kunci untuk sistem atau komponen yang dapat diperbaiki. Metrik ini merepresentasikan waktu operasional rata-rata yang diharapkan antara satu kegagalan dan kegagalan berikutnya. Nilai MTBF yang tinggi menunjukkan bahwa sistem tersebut sangat andal dan jarang mengalami kerusakan.','AKDING',30);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam diagram blok keandalan (reliability block diagram), komponen yang disusun secara paralel menunjukkan adanya sistem...','[{"key": "A", "text": "Seri"}, {"key": "B", "text": "Kompleks"}, {"key": "C", "text": "Redundansi"}, {"key": "D", "text": "Tunggal"}]'::jsonb,'A','Dalam analisis keandalan, diagram blok digunakan untuk memodelkan hubungan antar komponen dalam suatu sistem. Ketika komponen-komponen disusun secara paralel, ini mengindikasikan adanya redundansi. Artinya, ada lebih dari satu komponen atau jalur yang dapat menjalankan fungsi yang sama. Sistem hanya akan gagal jika semua komponen dalam susunan paralel tersebut gagal berfungsi, sehingga redundansi secara signifikan meningkatkan keandalan sistem secara keseluruhan.','AKDING',31);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jika sebuah mesin pembangkit memiliki dua pompa identik yang bekerja secara redundan (satu sebagai cadangan), keandalan sistem pompa tersebut akan...','[{"key": "A", "text": "Menurun"}, {"key": "B", "text": "Meningkat"}, {"key": "C", "text": "Tetap sama"}, {"key": "D", "text": "Tidak dapat ditentukan"}]'::jsonb,'A','Adanya dua pompa yang bekerja secara redundan berarti sistem tersebut memiliki cadangan. Jika pompa utama mengalami kegagalan, pompa cadangan dapat segera mengambil alih fungsinya, memastikan bahwa sistem tetap beroperasi. Kemampuan untuk menoleransi satu kegagalan ini secara langsung meningkatkan probabilitas bahwa sistem pompa akan berfungsi sesuai kebutuhan, yang berarti keandalannya meningkat.','AKDING',32);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'MTTR (Mean Time To Repair) adalah metrik yang digunakan untuk mengukur...','[{"key": "A", "text": "Seberapa sering suatu sistem gagal"}, {"key": "B", "text": "Kemudahan perawatan dan perbaikan suatu sistem (maintainability)"}, {"key": "C", "text": "Usia pakai total suatu komponen"}, {"key": "D", "text": "Ketersediaan (availability) sistem"}]'::jsonb,'A','MTTR, atau Mean Time To Repair (Waktu Rata-rata Untuk Perbaikan), adalah metrik yang mengukur efisiensi proses perawatan dan perbaikan. MTTR adalah waktu rata-rata yang diperlukan untuk memperbaiki sistem yang gagal dan mengembalikannya ke status operasional penuh. Nilai MTTR yang rendah menunjukkan bahwa sistem tersebut memiliki maintainability yang baik, artinya mudah dan cepat untuk diperbaiki.','AKDING',33);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Strategi perawatan yang dilakukan berdasarkan jadwal yang telah ditentukan tanpa melihat kondisi aktual peralatan disebut...','[{"key": "A", "text": "Predictive Maintenance"}, {"key": "B", "text": "Corrective Maintenance"}, {"key": "C", "text": "Preventive Maintenance"}, {"key": "D", "text": "Proactive Maintenance"}]'::jsonb,'A','Preventive Maintenance (Perawatan Pencegahan) adalah strategi perawatan proaktif di mana aktivitas pemeliharaan (seperti inspeksi, pelumasan, atau penggantian komponen) dilakukan pada interval yang telah ditentukan, baik berdasarkan kalender, jam operasi mesin, atau jumlah siklus produksi. Tujuannya adalah untuk mengurangi kemungkinan terjadinya kegagalan yang tidak terduga, berbeda dengan perawatan korektif yang baru dilakukan setelah kerusakan terjadi.','AKDING',34);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Keandalan (reliability) suatu sistem didefinisikan sebagai...','[{"key": "A", "text": "Kemampuan sistem untuk diperbaiki dengan cepat"}, {"key": "B", "text": "Probabilitas bahwa sistem akan berfungsi sesuai harapan selama periode waktu tertentu"}, {"key": "C", "text": "Biaya total kepemilikan sistem"}, {"key": "D", "text": "Jumlah kegagalan per satuan waktu"}]'::jsonb,'A','Ini adalah definisi teknis dan formal dari keandalan (reliability). Keandalan bukanlah jaminan bahwa sistem tidak akan pernah gagal, melainkan sebuah ukuran kuantitatif (probabilitas) dari kemampuannya untuk melakukan fungsi yang disyaratkan tanpa kegagalan, di bawah kondisi operasi yang ditentukan, dan untuk durasi waktu yang spesifik.','AKDING',35);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Analisis sistematis yang digunakan untuk mengidentifikasi potensi bahaya dan masalah operabilitas dalam suatu proses industri adalah...','[{"key": "A", "text": "FMEA (Failure Mode and Effects Analysis)"}, {"key": "B", "text": "HAZOP (Hazard and Operability Study)"}, {"key": "C", "text": "FTA (Fault Tree Analysis)"}, {"key": "D", "text": "JSA (Job Safety Analysis)"}]'::jsonb,'A','HAZOP adalah sebuah metode analisis bahaya yang sangat terstruktur dan sistematis, yang umum digunakan dalam industri proses kimia, perminyakan, dan pembangkit listrik. Tim multidisiplin akan memeriksa desain proses secara rinci, menggunakan serangkaian "kata pandu" (seperti ''Tidak Ada'', ''Lebih'', ''Kurang'', ''Kebalikan'') untuk merangsang pemikiran tentang bagaimana setiap parameter proses dapat menyimpang dari intensi desain dan apa konsekuensi dari penyimpangan tersebut.','AKDING',36);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tujuan utama dari mitigasi bahaya mekanis di unit produksi adalah...','[{"key": "A", "text": "Meningkatkan kecepatan produksi"}, {"key": "B", "text": "Mengurangi biaya operasional"}, {"key": "C", "text": "Mencegah cedera pada pekerja dan kerusakan pada peralatan"}, {"key": "D", "text": "Memenuhi standar penampilan pabrik"}]'::jsonb,'A','Mitigasi bahaya mekanis adalah inti dari program keselamatan mesin. Tujuannya adalah untuk mengidentifikasi, mengevaluasi, dan mengendalikan bahaya yang timbul dari mesin yang bergerak, berputar, atau memiliki titik jepit. Upaya ini dilakukan untuk melindungi aset paling berharga, yaitu pekerja, dari cedera serius, serta melindungi aset perusahaan, yaitu peralatan, dari kerusakan yang dapat menghentikan produksi.','AKDING',37);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pemasangan pelindung (machine guarding) pada bagian mesin yang bergerak seperti roda gigi atau sabuk adalah contoh dari upaya...','[{"key": "A", "text": "Pengendalian administratif"}, {"key": "B", "text": "Pengendalian rekayasa (engineering control)"}, {"key": "C", "text": "Penggunaan Alat Pelindung Diri (APD)"}, {"key": "D", "text": "Prosedur kerja aman"}]'::jsonb,'A','Hirarki pengendalian bahaya menempatkan pengendalian rekayasa sebagai salah satu metode yang paling efektif. Pengendalian ini melibatkan modifikasi fisik pada mesin atau lingkungan kerja untuk menghilangkan atau mengurangi bahaya pada sumbernya. Pemasangan pelindung fisik (machine guarding) adalah contoh utama, karena ia secara fisik mencegah kontak antara pekerja dan bagian mesin yang berbahaya, tanpa bergantung pada perilaku pekerja atau penggunaan APD.','AKDING',38);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Risiko dalam konteks K3 (Kesehatan dan Keselamatan Kerja) umumnya didefinisikan sebagai kombinasi dari...','[{"key": "A", "text": "Bahaya dan konsekuensi"}, {"key": "B", "text": "Probabilitas (likelihood) terjadinya insiden dan keparahan (severity) konsekuensinya"}, {"key": "C", "text": "Jumlah kecelakaan dan biaya pengobatan"}, {"key": "D", "text": "Peraturan pemerintah dan kebijakan perusahaan"}]'::jsonb,'A','Dalam manajemen keselamatan dan kesehatan kerja (K3), bahaya (hazard) adalah sumber potensi cedera, sedangkan risiko (risk) adalah evaluasi dari bahaya tersebut. Risiko secara formal dihitung dengan mempertimbangkan dua faktor: seberapa besar kemungkinan (probabilitas) insiden berbahaya itu terjadi, dan seberapa parah konsekuensinya (keparahan) jika insiden itu benar-benar terjadi. Manajemen risiko berfokus pada upaya untuk mengurangi salah satu atau kedua faktor ini.','AKDING',39);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Analisis yang dimulai dari sebuah kejadian puncak (kegagalan sistem) dan menelusuri ke belakang untuk menemukan kemungkinan penyebabnya adalah metode...','[{"key": "A", "text": "What-If Analysis"}, {"key": "B", "text": "Event Tree Analysis (ETA)"}, {"key": "C", "text": "Fault Tree Analysis (FTA)"}, {"key": "D", "text": "Hazard Identification (HAZID)"}]'::jsonb,'A','Fault Tree Analysis (FTA) adalah sebuah metode analisis risiko yang bersifat deduktif atau "top-down". Analisis dimulai dengan mendefinisikan sebuah kejadian puncak yang tidak diinginkan (misalnya, ''ledakan boiler'' atau ''kegagalan sistem pendingin''). Kemudian, analisis bekerja mundur secara sistematis untuk mengidentifikasi semua kemungkinan kombinasi kegagalan perangkat keras, kesalahan manusia, atau kejadian eksternal yang dapat menyebabkan terjadinya kejadian puncak tersebut, dengan menggunakan gerbang logika (AND, OR) untuk membangun pohon kesalahan.','AKDING',40);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pada siklus Rankine ideal, proses ekspansi uap di dalam turbin terjadi secara...','[{"key": "A", "text": "Isobarik (tekanan konstan)"}, {"key": "B", "text": "Isentropik (entropi konstan)"}, {"key": "C", "text": "Isotermal (suhu konstan)"}, {"key": "D", "text": "Isokhorik (volume konstan)"}]'::jsonb,'A','Dalam analisis siklus Rankine ideal, proses ekspansi uap panas bertekanan tinggi di dalam turbin diasumsikan terjadi secara isentropik. Artinya, proses tersebut dianggap adiabatik (tanpa perpindahan panas) dan reversibel (tanpa kerugian internal seperti gesekan). Ini adalah asumsi idealisasi yang menghasilkan kerja output maksimum yang mungkin dari turbin.','AKDING',1);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tujuan utama dari proses reheating (pemanasan ulang) pada siklus Rankine adalah untuk...','[{"key": "A", "text": "Meningkatkan tekanan di kondensor"}, {"key": "B", "text": "Mengurangi kerja yang dibutuhkan oleh pompa"}, {"key": "C", "text": "Menghindari kandungan uap air berlebih di akhir ekspansi turbin"}, {"key": "D", "text": "Menurunkan efisiensi termal siklus"}]'::jsonb,'A','Tujuan utama dari reheating adalah untuk meningkatkan kualitas uap (mengurangi fraksi cair) di tingkat akhir turbin. Uap yang terlalu "basah" (mengandung banyak tetesan air) dapat menyebabkan erosi pada sudu-sudu turbin, menurunkan efisiensi, dan berpotensi merusak turbin. Dengan memanaskan ulang uap, suhunya meningkat sehingga ia tetap dalam kondisi superpanas lebih lama selama ekspansi.','AKDING',2);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam siklus Brayton, komponen yang berfungsi untuk mengekstrak kerja dari gas panas bertekanan tinggi adalah...','[{"key": "A", "text": "Kompresor"}, {"key": "B", "text": "Ruang bakar (combustor)"}, {"key": "C", "text": "Turbin"}, {"key": "D", "text": "Kondensor"}]'::jsonb,'A','Setelah udara bertekanan tinggi dicampur dengan bahan bakar dan dibakar di ruang bakar, ia menghasilkan gas panas berenergi tinggi. Gas ini kemudian dialirkan untuk berekspansi melalui turbin. Saat berekspansi, gas tersebut mendorong sudu-sudu turbin untuk berputar, dan putaran inilah yang menghasilkan kerja mekanis untuk memutar kompresor dan generator (pada pembangkit listrik) atau menghasilkan daya dorong (pada mesin jet).','AKDING',3);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Menurut Hukum Pertama Termodinamika untuk sistem tertutup, perubahan energi internal ($\Delta$U) sama dengan...','[{"key": "A", "text": "Kerja yang dilakukan pada sistem"}, {"key": "B", "text": "Panas yang ditambahkan ke sistem"}, {"key": "C", "text": "Panas yang ditambahkan dikurangi kerja yang dilakukan oleh sistem (Q - W)"}, {"key": "D", "text": "Panas yang ditambahkan ditambah kerja yang dilakukan pada sistem (Q + W)"}]'::jsonb,'A','Hukum Pertama Termodinamika adalah pernyataan dari hukum kekekalan energi. Untuk sistem tertutup yang mengalami suatu proses, perubahan energi internal sistem (ΔU) adalah sama dengan jumlah total energi yang melintasi batas sistem. Ini dihitung sebagai jumlah panas (Q) yang ditransfer ke dalam sistem dikurangi jumlah kerja (W) yang dilakukan oleh sistem pada lingkungannya.','AKDING',4);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Efisiensi Carnot sebuah mesin kalor yang beroperasi antara reservoir suhu tinggi T_H = 800 K dan reservoir suhu rendah T_L = 400 K adalah...','[{"key": "A", "text": "25%"}, {"key": "B", "text": "50%"}, {"key": "C", "text": "75%"}, {"key": "D", "text": "100%"}]'::jsonb,'A','Efisiensi siklus Carnot (ηC) dihitung berdasarkan suhu absolut (dalam Kelvin) dari reservoir panas (T_H) dan reservoir dingin (T_L). Rumusnya adalah ηC = 1 -  . Dengan memasukkan nilai yang diberikan, ηC = 1 -   = 1 - 0.5 = 0.5. Dikonversi ke persentase, hasilnya adalah 50%.','AKDING',5);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses penambahan panas pada siklus Brayton ideal terjadi pada...','[{"key": "A", "text": "Tekanan konstan"}, {"key": "B", "text": "Volume konstan"}, {"key": "C", "text": "Suhu konstan"}, {"key": "D", "text": "Entropi konstan"}]'::jsonb,'A','Dalam siklus Brayton ideal, proses pembakaran atau penambahan panas dimodelkan terjadi pada tekanan konstan. Udara bertekanan tinggi dari kompresor masuk ke ruang bakar, dan saat bahan bakar ditambahkan dan dibakar, suhu dan volumenya meningkat secara drastis, tetapi tekanannya dianggap tetap konstan selama proses tersebut.','AKDING',6);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kehilangan energi (head loss) pada aliran fluida dalam pipa yang disebabkan oleh gesekan dengan dinding pipa disebut...','[{"key": "A", "text": "Minor losses"}, {"key": "B", "text": "Major losses"}, {"key": "C", "text": "Pressure drop"}, {"key": "D", "text": "Pumping head"}]'::jsonb,'A','Kehilangan energi atau head loss dalam sistem perpipaan dibagi menjadi dua kategori. Major losses adalah kehilangan energi akibat gesekan fluida di sepanjang bagian pipa yang lurus dan seragam. Sementara itu, minor losses adalah kehilangan energi yang terjadi akibat komponen seperti katup (valve), belokan (elbow), dan perubahan penampang pipa.','AKDING',7);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Menurut prinsip Bernoulli, jika kecepatan aliran fluida meningkat, maka tekanan statisnya akan...','[{"key": "A", "text": "Meningkat"}, {"key": "B", "text": "Menurun"}, {"key": "C", "text": "Tetap konstan"}, {"key": "D", "text": "Menjadi sama dengan tekanan dinamis"}]'::jsonb,'A','Ini adalah inti dari prinsip Bernoulli. Prinsip ini menyatakan adanya hubungan terbalik antara kecepatan fluida dan tekanan statisnya. Di area di mana fluida bergerak lebih cepat, tekanan statisnya akan lebih rendah, dan sebaliknya. Fenomena ini yang menjelaskan bagaimana sayap pesawat menghasilkan gaya angkat.','AKDING',8);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Venturimeter adalah alat yang digunakan untuk mengukur...','[{"key": "A", "text": "Tekanan fluida"}, {"key": "B", "text": "Viskositas fluida"}, {"key": "C", "text": "Ketinggian fluida"}, {"key": "D", "text": "Laju aliran (debit) fluida"}]'::jsonb,'A','Venturimeter bekerja berdasarkan prinsip Bernoulli. Alat ini terdiri dari sebuah pipa yang menyempit (disebut throat atau leher) dan kemudian melebar kembali. Dengan mengukur perbedaan tekanan antara bagian pipa yang lebar dan bagian yang sempit, laju aliran volume atau debit fluida dapat dihitung karena kecepatan fluida meningkat (dan tekanan menurun) di bagian yang sempit.','AKDING',9);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Fenomena kavitasi pada pompa atau turbin terjadi ketika tekanan fluida di suatu titik turun di bawah...','[{"key": "A", "text": "Tekanan atmosfer"}, {"key": "B", "text": "Tekanan uap jenuhnya"}, {"key": "C", "text": "Tekanan kritisnya"}, {"key": "D", "text": "Tekanan absolutnya"}]'::jsonb,'A','Kavitasi adalah fenomena terbentuknya gelembung-gelembung uap di dalam cairan yang mengalir. Ini terjadi ketika tekanan lokal dalam aliran fluida turun hingga mencapai atau di bawah tekanan uap jenuh cairan tersebut pada suhu operasinya. Gelembung-gelembung ini kemudian akan pecah (implode) ketika memasuki daerah bertekanan lebih tinggi, menghasilkan gelombang kejut yang dapat merusak komponen mesin seperti impeler pompa.','AKDING',10);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Viskositas pada fluida merupakan ukuran dari...','[{"key": "A", "text": "Kerapatan massanya"}, {"key": "B", "text": "Kemampuannya untuk dimampatkan"}, {"key": "C", "text": "Tahanan internalnya terhadap aliran"}, {"key": "D", "text": "Tegangan permukaannya"}]'::jsonb,'A','Viskositas adalah sifat fluida yang mengukur "ketebalan" atau tahanan internalnya terhadap gaya geser atau aliran. Fluida dengan viskositas tinggi (seperti madu) mengalir dengan lambat karena gesekan internal antar molekulnya besar, sedangkan fluida dengan viskositas rendah (seperti air) mengalir dengan mudah.','AKDING',11);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Aliran di mana sifat-sifat fluida (seperti kecepatan dan tekanan) di setiap titik tidak berubah terhadap waktu disebut aliran...','[{"key": "A", "text": "Seragam (uniform flow)"}, {"key": "B", "text": "Mantap (steady flow)"}, {"key": "C", "text": "Tak mantap (unsteady flow)"}, {"key": "D", "text": "Rotasional (rotational flow)"}]'::jsonb,'A','Aliran mantap atau steady flow adalah kondisi aliran di mana parameter-parameter aliran seperti kecepatan, tekanan, dan massa jenis di setiap titik dalam ruang tidak berubah seiring berjalannya waktu. Ini tidak berarti bahwa parameter tersebut sama di semua titik (itu disebut aliran seragam), tetapi nilainya di satu titik tertentu tetap konstan.','AKDING',12);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Hukum Fourier digunakan untuk menghitung laju perpindahan panas secara...','[{"key": "A", "text": "Konduksi"}, {"key": "B", "text": "Konveksi"}, {"key": "C", "text": "Radiasi"}, {"key": "D", "text": "Campuran"}]'::jsonb,'A','Hukum Fourier adalah persamaan dasar yang menggambarkan laju perpindahan panas melalui mekanisme konduksi. Hukum ini menyatakan bahwa laju aliran panas melalui suatu material sebanding dengan luas area yang tegak lurus terhadap aliran panas, gradien suhu, dan konstanta proporsionalitas yang disebut konduktivitas termal material.','AKDING',13);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Bilangan Nusselt (Nu) adalah parameter tak berdimensi yang merepresentasikan rasio antara perpindahan panas konveksi terhadap...','[{"key": "A", "text": "Perpindahan panas radiasi"}, {"key": "B", "text": "Perpindahan panas konduksi"}, {"key": "C", "text": "Kapasitas panas fluida"}, {"key": "D", "text": "Difusivitas termal"}]'::jsonb,'A','Bilangan Nusselt (Nu) adalah parameter penting dalam analisis perpindahan panas konveksi. Secara konseptual, bilangan ini membandingkan besarnya perpindahan panas yang terjadi melalui konveksi (pergerakan fluida) dengan perpindahan panas yang akan terjadi jika hanya ada konduksi murni melalui lapisan fluida yang diam. Nilai Nu yang lebih besar dari 1 menunjukkan bahwa konveksi meningkatkan perpindahan panas.','AKDING',14);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kemampuan suatu material untuk menghantarkan panas didefinisikan oleh properti yang disebut...','[{"key": "A", "text": "Kapasitas panas spesifik"}, {"key": "B", "text": "Difusivitas termal"}, {"key": "C", "text": "Konduktivitas termal"}, {"key": "D", "text": "Emisivitas"}]'::jsonb,'A','Konduktivitas termal (biasanya dilambangkan dengan ''k'') adalah sifat intrinsik material yang menunjukkan seberapa baik material tersebut menghantarkan panas. Material dengan konduktivitas termal tinggi, seperti logam, adalah konduktor panas yang baik, sedangkan material dengan konduktivitas termal rendah, seperti isolator (misalnya, gabus atau styrofoam), adalah konduktor panas yang buruk.','AKDING',15);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Perpindahan panas dari matahari ke bumi terjadi terutama melalui mekanisme...','[{"key": "A", "text": "Konduksi"}, {"key": "B", "text": "Konveksi"}, {"key": "C", "text": "Radiasi"}, {"key": "D", "text": "Adveksi"}]'::jsonb,'A','Ruang angkasa adalah vakum, yang berarti tidak ada medium (padat, cair, atau gas) untuk terjadinya konduksi atau konveksi. Oleh karena itu, satu-satunya cara energi panas dari matahari dapat melintasi ruang hampa dan mencapai bumi adalah melalui radiasi elektromagnetik.','AKDING',16);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Hukum pendinginan Newton menyatakan bahwa laju perpindahan panas konveksi sebanding dengan...','[{"key": "A", "text": "Kuadrat dari perbedaan suhu"}, {"key": "B", "text": "Perbedaan suhu antara permukaan dan fluida"}, {"key": "C", "text": "Konduktivitas termal fluida"}, {"key": "D", "text": "Viskositas fluida"}]'::jsonb,'A','Hukum pendinginan Newton adalah persamaan dasar untuk perpindahan panas konveksi. Hukum ini menyatakan bahwa laju perpindahan panas (Q) dari sebuah permukaan ke fluida di sekitarnya berbanding lurus dengan luas permukaan (A), koefisien perpindahan panas konveksi (h), dan perbedaan suhu ($\Delta$T) antara permukaan dan fluida.','AKDING',17);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah permukaan yang dapat menyerap semua radiasi yang datang padanya disebut...','[{"key": "A", "text": "Benda putih (white body)"}, {"key": "B", "text": "Benda abu-abu (gray body)"}, {"key": "C", "text": "Benda hitam (black body)"}, {"key": "D", "text": "Permukaan difus (diffuse surface)"}]'::jsonb,'A','Benda hitam adalah sebuah benda ideal teoretis dalam fisika termal yang memiliki sifat menyerap semua radiasi elektromagnetik yang jatuh padanya, tanpa memantulkan atau meneruskannya. Karena ia adalah penyerap yang sempurna, menurut hukum Kirchhoff tentang radiasi termal, ia juga merupakan pemancar (emitor) radiasi yang paling sempurna.','AKDING',18);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pada kurva tegangan-regangan, titik di mana material mencapai kekuatan maksimumnya sebelum mulai mengalami necking (pengecilan penampang) disebut...','[{"key": "A", "text": "Batas proporsional"}, {"key": "B", "text": "Titik luluh (yield point)"}, {"key": "C", "text": "Tegangan tarik ultimate (ultimate tensile strength)"}, {"key": "D", "text": "Titik putus (fracture point)"}]'::jsonb,'A','Ultimate Tensile Strength (UTS) adalah nilai tegangan maksimum yang dapat ditahan oleh suatu material saat ditarik atau diregangkan. Titik ini merupakan puncak dari kurva tegangan-regangan. Setelah melewati titik UTS, material akan mulai mengalami fenomena necking, di mana penampangnya mulai mengecil secara lokal sebelum akhirnya patah.','AKDING',19);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kemampuan material untuk mengalami deformasi plastis yang besar sebelum patah disebut...','[{"key": "A", "text": "Kekuatan (strength)"}, {"key": "B", "text": "Kekakuan (stiffness)"}, {"key": "C", "text": "Keuletan (ductility)"}, {"key": "D", "text": "Kekerasan (hardness)"}]'::jsonb,'A','Keuletan adalah ukuran sejauh mana suatu material dapat mengalami deformasi plastis (perubahan bentuk permanen) di bawah tegangan tarik sebelum patah. Material yang ulet, seperti tembaga atau baja ringan, dapat ditarik menjadi kawat tipis. Sebaliknya, material yang getas (brittle), seperti kaca atau besi cor, akan patah dengan sedikit atau tanpa deformasi plastis.','AKDING',20);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Rasio antara regangan lateral (menyamping) terhadap regangan aksial (memanjang) ketika material ditarik disebut...','[{"key": "A", "text": "Modulus Young"}, {"key": "B", "text": "Modulus geser"}, {"key": "C", "text": "Rasio Poisson"}, {"key": "D", "text": "Faktor keamanan"}]'::jsonb,'A','Rasio Poisson adalah ukuran dari fenomena kontraksi transversal. Ketika sebuah material diregangkan dalam satu arah (aksial), ia cenderung menipis atau menyusut dalam arah yang tegak lurus (lateral). Rasio Poisson adalah perbandingan antara regangan lateral yang negatif (karena menyusut) dengan regangan aksial.','AKDING',21);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Material komposit yang terdiri dari serat (fiber) yang tertanam dalam sebuah matriks (matrix) disebut...','[{"key": "A", "text": "Particulate composite"}, {"key": "B", "text": "Laminated composite"}, {"key": "C", "text": "Fibrous composite"}, {"key": "D", "text": "Sandwich composite"}]'::jsonb,'A','Komposit serat (fibrous composite) adalah jenis material komposit yang kekuatannya didominasi oleh serat berkekuatan tinggi (seperti serat karbon, kaca, atau aramid) yang disatukan oleh material matriks yang lebih lemah (biasanya polimer). Matriks berfungsi untuk mengikat serat, mendistribusikan beban, dan melindungi serat dari kerusakan.','AKDING',22);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pengujian impak Charpy atau Izod digunakan untuk mengukur...','[{"key": "A", "text": "Kekuatan lelah (fatigue strength) material"}, {"key": "B", "text": "Ketangguhan (toughness) material"}, {"key": "C", "text": "Kekerasan (hardness) material"}, {"key": "D", "text": "Batas luluh (yield strength) material"}]'::jsonb,'A','Pengujian impak seperti Charpy dan Izod dirancang untuk menentukan jumlah energi yang dapat diserap oleh suatu material selama proses patah akibat beban kejut. Energi yang diserap ini adalah ukuran ketangguhan impak material, yang menunjukkan kemampuannya untuk menahan beban kejut tanpa mengalami patah getas.','AKDING',23);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Deformasi yang bergantung pada waktu pada material yang mengalami tegangan konstan pada suhu tinggi disebut...','[{"key": "A", "text": "Fatigue"}, {"key": "B", "text": "Creep (rayapan)"}, {"key": "C", "text": "Relaksasi"}, {"key": "D", "text": "Buckling"}]'::jsonb,'A','Creep adalah deformasi permanen yang terjadi secara perlahan-lahan (bergantung waktu) pada material yang dikenai tegangan mekanis konstan, terutama pada suhu yang tinggi (relatif terhadap titik leleh material). Fenomena ini menjadi pertimbangan desain yang sangat penting untuk komponen yang beroperasi pada suhu tinggi, seperti sudu turbin atau pipa uap.','AKDING',24);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses manufaktur yang menggunakan cetakan sekali pakai yang terbuat dari pasir untuk membentuk logam cair adalah...','[{"key": "A", "text": "Die casting"}, {"key": "B", "text": "Investment casting"}, {"key": "C", "text": "Sand casting (pengecoran pasir)"}, {"key": "D", "text": "Forging (penempaan)"}]'::jsonb,'A','Pengecoran pasir adalah salah satu proses pengecoran logam tertua dan paling umum. Proses ini melibatkan pembuatan cetakan dari campuran pasir yang dipadatkan di sekitar sebuah pola (model dari komponen yang akan dibuat). Setelah pola diangkat, rongga cetakan diisi dengan logam cair. Setelah logam membeku, cetakan pasir dihancurkan untuk mengeluarkan produk cor.','AKDING',25);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses perlakuan panas annealing pada baja bertujuan untuk...','[{"key": "A", "text": "Meningkatkan kekerasan dan kekuatan"}, {"key": "B", "text": "Menghilangkan tegangan sisa dan melunakkan material"}, {"key": "C", "text": "Menciptakan lapisan permukaan yang keras"}, {"key": "D", "text": "Meningkatkan ketahanan korosi"}]'::jsonb,'A','Annealing adalah proses perlakuan panas yang melibatkan pemanasan material (biasanya logam) ke suhu tertentu, menahannya pada suhu tersebut untuk beberapa waktu, lalu mendinginkannya secara perlahan. Tujuan utamanya adalah untuk melunakkan material, meningkatkan keuletannya, dan menghilangkan tegangan internal yang mungkin timbul dari proses pengerjaan sebelumnya (seperti pengerolan atau penempaan).','AKDING',26);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam pemesinan bubut (turning), gerakan utama yang menghasilkan pemotongan adalah...','[{"key": "A", "text": "Gerak putar pahat"}, {"key": "B", "text": "Gerak putar benda kerja"}, {"key": "C", "text": "Gerak translasi benda kerja"}, {"key": "D", "text": "Gerak maju-mundur pahat"}]'::jsonb,'A','Pada mesin bubut, benda kerja dijepit pada chuck dan diputar pada kecepatan tinggi. Pahat potong, yang dipasang pada tool post, digerakkan secara linear sejajar atau tegak lurus terhadap sumbu putaran benda kerja. Kombinasi dari gerak putar benda kerja dan gerak makan (feed) pahat inilah yang menghasilkan proses pemotongan material.','AKDING',27);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Suaian paksa (interference fit) adalah jenis suaian di mana...','[{"key": "A", "text": "Terdapat kelonggaran antara poros dan lubang"}, {"key": "B", "text": "Ukuran poros lebih besar dari ukuran lubang sebelum perakitan"}, {"key": "C", "text": "Ukuran poros dan lubang persis sama"}, {"key": "D", "text": "Kelonggaran atau kesesakan bisa terjadi tergantung toleransi"}]'::jsonb,'A','Suaian paksa atau interference fit (juga dikenal sebagai press fit) adalah jenis perakitan di mana dimensi poros sedikit lebih besar daripada dimensi lubang. Perakitan ini memerlukan gaya untuk memasukkan poros ke dalam lubang (misalnya dengan mesin press) atau dengan memanfaatkan ekspansi/kontraksi termal. Hasilnya adalah sambungan yang sangat kuat dan kencang karena adanya tekanan kontak antara kedua komponen.','AKDING',28);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses Computer Numerical Control (CNC) dalam manufaktur mengacu pada...','[{"key": "A", "text": "Penggunaan komputer untuk merancang produk (CAD)"}, {"key": "B", "text": "Otomatisasi mesin perkakas menggunakan program komputer"}, {"key": "C", "text": "Inspeksi kualitas produk menggunakan sensor"}, {"key": "D", "text": "Perencanaan proses produksi secara digital"}]'::jsonb,'A','CNC (Computer Numerical Control) adalah teknologi yang menggunakan instruksi terprogram dalam bentuk kode (seperti G-code) untuk mengontrol pergerakan dan operasi mesin perkakas secara otomatis. Komputer menerjemahkan program ini menjadi sinyal-sinyal yang menggerakkan motor dan aktuator pada mesin, memungkinkan pembuatan komponen yang kompleks dengan presisi dan keterulangan yang tinggi.','AKDING',29);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Ketersediaan (Availability) sebuah sistem dihitung dari metrik MTBF dan MTTR dengan rumus...','[{"key": "A", "text": "MTBF / MTTR"}, {"key": "B", "text": "MTTR / MTBF"}, {"key": "C", "text": "MTBF / (MTBF + MTTR)"}, {"key": "D", "text": "(MTBF + MTTR) / MTBF"}]'::jsonb,'A','Ketersediaan (Availability) adalah probabilitas bahwa sebuah sistem akan beroperasi dan berfungsi dengan baik ketika dibutuhkan. Untuk sistem yang dapat diperbaiki, ketersediaan inheren dihitung sebagai rasio waktu operasional (MTBF) terhadap total waktu siklus (waktu operasional ditambah waktu perbaikan, atau MTBF + MTTR).','AKDING',30);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Strategi perawatan yang menggunakan sensor dan analisis data untuk memprediksi kapan sebuah komponen akan gagal disebut...','[{"key": "A", "text": "Preventive Maintenance"}, {"key": "B", "text": "Corrective Maintenance"}, {"key": "C", "text": "Proactive Maintenance"}, {"key": "D", "text": "Predictive Maintenance"}]'::jsonb,'A','Predictive Maintenance (PdM) atau perawatan prediktif adalah strategi perawatan yang sangat proaktif. Alih-alih melakukan perawatan berdasarkan jadwal tetap (preventif), PdM menggunakan berbagai teknik pemantauan kondisi (seperti analisis getaran, termografi, atau analisis oli) dan analisis data untuk memantau kesehatan peralatan secara real-time dan memprediksi kapan kegagalan akan terjadi, sehingga perbaikan dapat dijadwalkan tepat sebelum kerusakan.','AKDING',31);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam diagram blok keandalan, komponen yang disusun secara seri berarti kegagalan salah satu komponen akan...','[{"key": "A", "text": "Meningkatkan keandalan sistem"}, {"key": "B", "text": "Menyebabkan seluruh sistem gagal"}, {"key": "C", "text": "Tidak berpengaruh pada sistem"}, {"key": "D", "text": "Diambil alih oleh komponen lain"}]'::jsonb,'A','Dalam konfigurasi seri, komponen-komponen terhubung dalam satu jalur tunggal. Agar sistem dapat berfungsi, semua komponen dalam jalur tersebut harus berfungsi. Oleh karena itu, jika salah satu saja komponen dalam susunan seri mengalami kegagalan, seluruh jalur akan terputus dan sistem secara keseluruhan akan berhenti beroperasi.','AKDING',32);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Analisis Root Cause Failure Analysis (RCFA) bertujuan untuk...','[{"key": "A", "text": "Memperbaiki kerusakan secepat mungkin"}, {"key": "B", "text": "Mengidentifikasi penyebab paling mendasar dari suatu kegagalan"}, {"key": "C", "text": "Menjadwalkan kegiatan perawatan preventif"}, {"key": "D", "text": "Menghitung keandalan sistem"}]'::jsonb,'A','Root Cause Failure Analysis (RCFA) adalah proses pemecahan masalah yang sistematis yang bertujuan untuk menemukan akar penyebab sebenarnya dari suatu masalah atau kegagalan. Tujuannya bukan hanya untuk mengatasi gejala (misalnya, mengganti komponen yang rusak), tetapi untuk memahami mengapa kegagalan itu terjadi sejak awal, sehingga tindakan korektif yang permanen dapat diterapkan untuk mencegahnya terulang kembali.','AKDING',33);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Probabilitas bahwa suatu komponen yang dapat diperbaiki akan berfungsi pada waktu tertentu disebut...','[{"key": "A", "text": "Keandalan (Reliability)"}, {"key": "B", "text": "Ketersediaan (Availability)"}, {"key": "C", "text": "Kemudahan Perawatan (Maintainability)"}, {"key": "D", "text": "Usia Pakai (Lifetime)"}]'::jsonb,'A','Ada perbedaan antara Keandalan (Reliability) dan Ketersediaan (Availability). Keandalan adalah probabilitas berfungsi tanpa kegagalan selama interval waktu tertentu. Ketersediaan adalah probabilitas bahwa sistem berfungsi pada satu titik waktu tertentu, yang sudah memperhitungkan waktu henti untuk perbaikan. Jadi, availability cocok untuk komponen yang dapat diperbaiki.','AKDING',34);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah sistem memiliki tiga komponen identik secara paralel. Jika keandalan satu komponen adalah R = 0.8, maka keandalan sistem total adalah...','[{"key": "A", "text": "0.8"}, {"key": "B", "text": "0.992"}, {"key": "C", "text": "0.512"}, {"key": "D", "text": "2.4"}]'::jsonb,'A','Untuk sistem dengan komponen paralel, sistem hanya akan gagal jika semua komponen gagal. Pertama, hitung probabilitas kegagalan satu komponen: F = 1 - R = 1 - 0.8 = 0.2. Kemudian, hitung probabilitas semua tiga komponen gagal bersamaan: F_sistem = F1 * F2 * F3 = 0.2 * 0.2 * 0.2 = 0.008. Terakhir, keandalan sistem total adalah kebalikan dari probabilitas kegagalan sistem: R_sistem = 1 - F_sistem = 1 - 0.008 = 0.992.','AKDING',35);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Hirarki pengendalian risiko menempatkan metode yang paling efektif pada urutan teratas, yaitu...','[{"key": "A", "text": "Alat Pelindung Diri (APD)"}, {"key": "B", "text": "Pengendalian Administratif"}, {"key": "C", "text": "Eliminasi bahaya"}, {"key": "D", "text": "Pengendalian Rekayasa"}]'::jsonb,'A','Hirarki pengendalian risiko adalah pendekatan bertingkat untuk mengelola keselamatan di tempat kerja. Urutan dari yang paling efektif hingga yang kurang efektif adalah: 1) Eliminasi (menghilangkan bahaya sepenuhnya), 2) Substitusi (mengganti dengan yang lebih aman), 3) Pengendalian Rekayasa (mengisolasi orang dari bahaya), 4) Pengendalian Administratif (mengubah cara orang bekerja), dan 5) Alat Pelindung Diri (APD). Eliminasi adalah yang paling ideal karena menghilangkan masalah pada akarnya.','AKDING',36);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Analisis Failure Mode and Effects Analysis (FMEA) adalah metode yang digunakan untuk...','[{"key": "A", "text": "Mengidentifikasi potensi mode kegagalan dalam suatu sistem dan efeknya"}, {"key": "B", "text": "Menganalisis operabilitas suatu proses industri"}, {"key": "C", "text": "Membuat pohon logika penyebab suatu kegagalan"}, {"key": "D", "text": "Menganalisis keselamatan suatu pekerjaan (JSA)"}]'::jsonb,'A','FMEA adalah metode proaktif yang digunakan selama tahap desain atau analisis sistem untuk mengidentifikasi semua cara yang mungkin di mana suatu komponen atau proses dapat gagal (mode kegagalan), dan kemudian menganalisis konsekuensi atau efek dari setiap kegagalan tersebut pada sistem secara keseluruhan. Ini membantu memprioritaskan risiko dan merancang tindakan pencegahan.','AKDING',37);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Lockout/Tagout (LOTO) adalah prosedur keselamatan yang dirancang untuk...','[{"key": "A", "text": "Mencegah mesin dari pencurian"}, {"key": "B", "text": "Memberi label pada mesin yang baru"}, {"key": "C", "text": "Memastikan mesin tidak dapat dihidupkan secara tidak sengaja selama perbaikan"}, {"key": "D", "text": "Mengunci area produksi saat tidak digunakan"}]'::jsonb,'A','Prosedur LOTO adalah praktik keselamatan kerja yang krusial. Prosedur ini melibatkan pemutusan sumber energi mesin (listrik, hidrolik, pneumatik) dan pemasangan gembok (Lockout) serta label peringatan (Tagout) pada perangkat isolasi energi. Ini memastikan bahwa mesin tidak dapat diaktifkan kembali secara tidak sengaja atau oleh orang lain saat sedang dalam proses perawatan atau perbaikan, sehingga melindungi personel dari cedera serius.','AKDING',38);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Bahaya (hazard) dalam konteks K3 didefinisikan sebagai...','[{"key": "A", "text": "Probabilitas terjadinya kecelakaan"}, {"key": "B", "text": "Konsekuensi dari sebuah insiden"}, {"key": "C", "text": "Sesuatu yang memiliki potensi untuk menyebabkan cedera atau kerugian"}, {"key": "D", "text": "Kegagalan untuk mengikuti prosedur"}]'::jsonb,'A','Bahaya (hazard) adalah sumber atau situasi yang melekat yang memiliki potensi untuk menyebabkan kerusakan, baik itu cedera pada manusia, kerusakan properti, kerusakan lingkungan, atau kombinasi dari semuanya. Contohnya adalah lantai yang licin, kabel listrik yang terbuka, atau bahan kimia beracun. Bahaya itu sendiri belum tentu menyebabkan kerugian, tetapi potensinya ada.','AKDING',39);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah interlock pada pelindung mesin (machine guard) berfungsi untuk...','[{"key": "A", "text": "Mengunci pelindung agar tidak bisa dibuka"}, {"key": "B", "text": "Memberikan peringatan suara jika pelindung dibuka"}, {"key": "C", "text": "Menghentikan operasi mesin jika pelindung dibuka"}, {"key": "D", "text": "Menerangi area kerja di sekitar pelindung"}]'::jsonb,'A','Interlock adalah perangkat keselamatan yang menghubungkan status pelindung mesin (guard) dengan sirkuit kontrol daya mesin. Jika pelindung dibuka atau dilepas saat mesin sedang beroperasi, sakelar interlock akan terpicu dan secara otomatis mengirimkan sinyal untuk menghentikan mesin. Ini mencegah operator menjangkau bagian berbahaya yang sedang bergerak.','AKDING',40);
